import io, os
NL=chr(10)
def edit(path, pairs, must=True):
    x=io.open(path,encoding='utf-8').read()
    for a,b in pairs:
        if a in x: x=x.replace(a,b,1)
        elif must: raise SystemExit('未找到: %s -> %s' % (path, a[:50]))
    io.open('_tmp_e.txt','w',encoding='utf-8',newline=NL).write(x); os.replace('_tmp_e.txt',path); print('  已更新', path)

